<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { decodeReferenceBook, type ReferenceBookView } from '@lanjian/hosted-contracts'
import { http, messageOf } from '../api/http'
const props = defineProps<{ compact?: boolean }>()
const host = ref<HTMLElement>(), book = ref<ReferenceBookView>(), selected = ref(0), notes = ref(false), error = ref('')
const chapter = computed(() => book.value?.chapters[selected.value])
const paragraphs = computed(() => chapter.value?.content.split('\n\n').slice(0, props.compact ? 2 : 4) ?? [])
let observer: IntersectionObserver | undefined
async function load() { error.value = ''; try { book.value = decodeReferenceBook(await http.request('/api/reference-book')) } catch (e) { error.value = messageOf(e) } }
onMounted(() => { observer = new IntersectionObserver(([entry]) => { if (entry?.isIntersecting) { observer?.disconnect(); void load() } }, { rootMargin: '250px' }); observer.observe(host.value!) })
onBeforeUnmount(() => observer?.disconnect())
</script>
<template>
  <section ref="host" class="sample-desk" :class="{ compact }" aria-label="参考书试读">
    <div class="desk-toolbar"><span>翻几页，看看故事怎样写成。</span><div class="desk-switch"><button :aria-pressed="!notes" @click="notes = false">读正文</button><button :aria-pressed="notes" @click="notes = true">看章纲</button></div></div>
    <div class="open-book"><aside class="open-book-left"><p class="desk-label">岚笺原创 / 阅读副本</p><h3>渡口最后一盏灯</h3><span class="book-volume">灯照归途</span><nav v-if="book" aria-label="试读章节"><button v-for="(item, i) in book.chapters" :key="item.title" :aria-current="selected === i ? 'true' : undefined" @click="selected = i"><small>0{{ i + 1 }}</small><span>{{ item.title }}</span><span>→</span></button></nav><p class="desk-note">设定、章纲与正文<br>可以打开来，逐章对照。</p></aside><div class="open-book-right"><p v-if="error" role="alert">{{ error }} <button @click="load">重新读取</button></p><p v-else-if="!chapter" role="status">正在翻开参考书…</p><article v-else :key="`${selected}-${notes}`" class="sample-page"><p class="desk-label">{{ notes ? 'CHAPTER OUTLINE / 章纲' : 'READING / 正文试读' }} <span>0{{ selected + 1 }}</span></p><h4>{{ chapter.title }}</h4><div v-if="notes" class="desk-notes">{{ chapter.notes }}</div><div v-else class="desk-prose"><p v-for="(paragraph, i) in paragraphs" :key="i">{{ paragraph }}</p></div><a class="desk-read" href="/app/reference">读完这一章 →</a></article></div></div>
    <p class="desk-caption">以上文字来自内置参考书。阅读与复制不调用模型、不消耗积分。</p>
  </section>
</template>
<style scoped>
